import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { MaxDwellComponent } from './max-dwell.component';

const routes: Routes = [{ path: '', component: MaxDwellComponent }];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule]
})
export class MaxDwellRoutingModule { }
